/// <summary>
/// AR-67 email notification batch job  
/// </summary>
public class METAR67EmailFailureController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    // call service class and service class method
    super(classStr(METAR67EmailFailureService), methodStr(METAR67EmailFailureService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Construct METAR67EmailFailureController class
/// </summary>
public static METAR67EmailFailureController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METAR67EmailFailureController controller;
    controller = new METAR67EmailFailureController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

    public static void main(Args _args)

    {
        METAR67EmailFailureController controller;

        controller = METAR67EmailFailureController::construct();
        controller.parmArgs(_args);
        controller.parmShowDialog(true);
        controller.startOperation();
    }

/// <summary>
/// Caption of a batch job
/// </summary>
public ClassDescription defaultCaption()
{
    return "@MET:AR67EmailFailureNotification";
}
